// it. The imports are type-only and erased at build time, so this never ships
// anything to the bundle — it just keeps the import specifier honest.
const apiTypes = fileURLToPath(new URL('../../packages/api-types/index.ts', import.meta.url))

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@labmate/api-types': apiTypes,
    },
  },
  server: {
    port: 5173,
    strictPort: false,
  },
})

