                          className="ban-btn"
                          disabled={actions.banColumn.isPending && banPending === col.name}
                          onClick={() => actions.banColumn.mutate(col.name)}
                        >
                          {actions.banColumn.isPending && banPending === col.name ? '…' : 'BAN'}
                        </button>
                      ) : null}
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
