}

export function RunTable({
  runs = [],
  hypotheses = [],
  critiques = [],
  metricKey,
  loading = false,
}: {
  runs?: Run[]
  hypotheses?: Hypothesis[]
  critiques?: Critique[]
  metricKey?: string
  loading?: boolean
}) {
  const familyOf = (hypId: string) => hypotheses.find((h) => h.id === hypId)?.model_family

