          fix: { type: 'string', description: 'concrete, minimal fix' },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['isReal', 'severity', 'reasoning', 'fix'],
