  .sort((a, b) => ({ high: 0, medium: 1, low: 2 })[a.severity] - ({ high: 0, medium: 1, low: 2 })[b.severity])

const rejected = all.filter((x) => !x.verdict?.isReal).length
return { confirmed, confirmedCount: confirmed.length, rejectedCount: rejected }

