  loading?: boolean
}) {
  const flag = detail ? methodologicalFlag(detail) : undefined
  const entries = detail ? buildLedger(detail) : []

  const inner = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!detail || entries.length === 0) {
